-- Requiere que InitDatabase.sql ya se haya ejecutado (tablas creadas).
-- Es seguro re-ejecutarlo: todo el seed corre en UNA transaccion (todo o nada), y se
-- omite por completo solo si el idioma base (ES) ya existe, lo que implica que el commit llego a ocurrir
-- (el guard no depende del usuario admin: si alguien lo elimina, un reinicio del init no debe re-sembrar y fallar).
USE GestorTransporteCG;
GO

SET XACT_ABORT ON;

IF NOT EXISTS (SELECT 1 FROM dbo.Idioma WHERE Codigo = N'ES')
BEGIN
    BEGIN TRY
    BEGIN TRANSACTION;

    -- Idiomas: deben existir antes que los usuarios (FK_Usuario_Idioma).
    -- Las etiquetas y sus traducciones se cargan al final de este script (TRADUCCIONES INICIALES).

    VALUES (
        'd1eda407-3582-4e0c-85cc-ae51eb67b826',
        'admin',
        '8C6976E5B5410415BDE908BD4DEE15DFB167A9C873FC4BB8A81F6F2AB448A918',
        'admin@gmail.com',
        '+54 1120202020',
        0,
        DEFAULT,
        DEFAULT,
        '8D35CFBE2038902867920E5E76AFC58508CBDB31EB92820A1F1F444FF994A615'
    );

    VALUES (
        'Usuario',
        'EE3883C5E753048F5D8E02A1EED6B72FE04574293EFC6F894D103D8C94AAF0F2'
    );





    COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO

-- ---------------------------------------------------------
-- PERMISOS AGREGADOS DESPUES DEL SEED INICIAL
-- El seed de arriba se omite si la base ya existe, por lo que los permisos nuevos se
-- agregan aca de forma idempotente para que tambien lleguen a instalaciones previas.
-- ---------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM dbo.Permiso WHERE Nombre = 'PERM-ELIMINAR-SANCION' AND EsPerfil = 0)
BEGIN
END

IF EXISTS (SELECT 1 FROM dbo.Permiso WHERE Nombre = 'PERF-ADMIN' AND EsPerfil = 1)
   AND NOT EXISTS (
       SELECT 1 FROM dbo.PermisoRelacion
       WHERE ID_Padre = (SELECT ID FROM dbo.Permiso WHERE Nombre = 'PERF-ADMIN' AND EsPerfil = 1)
         AND ID_Hijo = (SELECT ID FROM dbo.Permiso WHERE Nombre = 'PERM-ELIMINAR-SANCION' AND EsPerfil = 0))
BEGIN
    VALUES (
        (SELECT ID FROM dbo.Permiso WHERE Nombre = 'PERF-ADMIN' AND EsPerfil = 1),
        (SELECT ID FROM dbo.Permiso WHERE Nombre = 'PERM-ELIMINAR-SANCION' AND EsPerfil = 0)
    );
END

GO

-- ---------------------------------------------------------
-- TRADUCCIONES INICIALES (ES / EN / PT)
-- Etiquetas de todos los formularios y mensajes con su texto en los tres idiomas.
-- Es idempotente y nunca pisa textos existentes: solo agrega las etiquetas y traducciones
-- que falten, asi tambien completa bases ya inicializadas sin perder lo editado desde la
-- gestion de idiomas. Las etiquetas que se agreguen en el futuro las registra la aplicacion.
-- ---------------------------------------------------------
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @Traducciones TABLE (
    Clave VARCHAR(200) NOT NULL PRIMARY KEY,
    Formulario VARCHAR(100) NULL,
    ES NVARCHAR(MAX) NOT NULL,
    EN NVARCHAR(MAX) NOT NULL,
    PT NVARCHAR(MAX) NOT NULL
);


BEGIN TRANSACTION;

SELECT t.Clave, t.Formulario
FROM @Traducciones t
WHERE NOT EXISTS (SELECT 1 FROM dbo.Etiqueta e WHERE e.Clave = t.Clave);

SELECT e.IdEtiqueta, v.CodigoIdioma, v.Texto
FROM @Traducciones t
INNER JOIN dbo.Etiqueta e ON e.Clave = t.Clave
CROSS APPLY (VALUES ('ES', t.ES), ('EN', t.EN), ('PT', t.PT)) v (CodigoIdioma, Texto)
WHERE EXISTS (SELECT 1 FROM dbo.Idioma i WHERE i.Codigo = v.CodigoIdioma)
  AND NOT EXISTS (SELECT 1 FROM dbo.Traduccion tr WHERE tr.IdEtiqueta = e.IdEtiqueta AND tr.CodigoIdioma = v.CodigoIdioma);

COMMIT TRANSACTION;
GO
